24	/// A world that provides access to the operating system.
25	pub struct SystemWorld {
26	    /// The working directory.
27	    workdir: Option<PathBuf>,
28	    /// Typst's standard library.
29	    library: LazyHash<Library>,
30	    /// Metadata about discovered fonts and lazily loaded fonts.
31	    fonts: LazyLock<FontStore, Box<dyn Fn() -> FontStore + Send + Sync>>,
32	    /// Maps file ids to source files and buffers.
33	    files: FileStore<SystemFiles>,
34	    /// The current datetime if requested. This is stored here to ensure it is
35	    /// always the same within one compilation.
36	    /// Reset between compilations if not [`Time::Fixed`].
37	    now: Time,
38	}
39	
40	impl SystemWorld {
41	    /// Creates a new system world.
42	    pub fn new(
43	        input: Option<&Input>,
44	        world_args: &'static WorldArgs,
45	        process_args: &ProcessArgs,
46	    ) -> Result<Self, WorldCreationError> {
47	        // Set up the thread pool.
48	        if let Some(jobs) = process_args.jobs {
49	            rayon::ThreadPoolBuilder::new()
50	                .num_threads(jobs)
51	                .use_current_thread()
52	                .build_global()
53	                .ok();
54	        }
55	
56	        let library = {
57	            // Convert the input pairs to a dictionary.
58	            let inputs: Dict = world_args
59	                .inputs
60	                .iter()
61	                .map(|(k, v)| (k.as_str().into(), v.as_str().into_value()))
62	                .collect();
63	
64	            let features =
65	                process_args.features.iter().copied().map(Into::into).collect();
66	
67	            Library::builder().with_inputs(inputs).with_features(features).build()
68	        };
69	
70	        let now = match world_args.creation_timestamp {
71	            Some(time) => Time::fixed_timestamp(time)
72	                .map_err(|_| WorldCreationError::InvalidTimestamp)?,
73	            None => Time::system(),
74	        };
75	
76	        Ok(Self {
77	            workdir: std::env::current_dir().ok(),
78	            library: LazyHash::new(library),
79	            fonts: LazyLock::new(Box::new(|| {
80	                crate::fonts::discover_fonts(&world_args.font)
81	            })),
82	            files: FileStore::new(SystemFiles::new(input, world_args)?),
83	            now,
84	        })
85	    }
86	
87	    /// The project root relative to which absolute paths are resolved.
88	    pub fn root(&self) -> &Path {
89	        self.files.loader().project.path()
90	    }
91	
92	    /// The current working directory.
93	    pub fn workdir(&self) -> &Path {
94	        self.workdir.as_deref().unwrap_or(Path::new("."))
95	    }
96	
97	    /// Return all paths the last compilation depended on.
98	    pub fn dependencies(&mut self) -> impl Iterator<Item = PathBuf> + '_ {
99	        let (loader, deps) = self.files.dependencies();
100	        deps.filter_map(|id| loader.resolve(id).ok())
101	    }
102	
103	    /// Reset the compilation state in preparation of a new compilation.
104	    pub fn reset(&mut self) {
105	        self.files.reset();
106	        self.now.reset();
107	    }
108	
109	    /// Forcibly scan fonts instead of doing it lazily upon the first access.
110	    ///
111	    /// Does nothing if the fonts were already scanned.
112	    pub fn scan_fonts(&mut self) {
113	        LazyLock::force(&self.fonts);
114	    }
115	}
