117	impl World for SystemWorld {
118	    fn library(&self) -> &LazyHash<Library> {
119	        &self.library
120	    }
121	
122	    fn book(&self) -> &LazyHash<FontBook> {
123	        self.fonts.book()
124	    }
125	
126	    fn main(&self) -> FileId {
127	        self.files.loader().main
128	    }
129	
130	    fn source(&self, id: FileId) -> FileResult<Source> {
131	        self.files.source(id)
132	    }
133	
134	    fn file(&self, id: FileId) -> FileResult<Bytes> {
135	        self.files.file(id)
136	    }
137	
138	    fn font(&self, index: usize) -> Option<Font> {
139	        self.fonts.font(index)
140	    }
141	
142	    fn today(&self, offset: Option<Duration>) -> Option<Datetime> {
143	        self.now.today(offset)
144	    }
145	}
