147	impl DiagnosticWorld for SystemWorld {
148	    fn name(&self, id: FileId) -> String {
149	        let vpath = id.vpath();
150	        match id.root() {
151	            VirtualRoot::Project => {
152	                // Try to express the path relative to the working directory.
153	                vpath
154	                    .realize(self.root())
155	                    .ok()
156	                    .and_then(|rooted| pathdiff::diff_paths(rooted, self.workdir()))
157	                    .map(|path| path.to_string_lossy().into_owned())
158	                    .unwrap_or_else(|| vpath.get_without_slash().into())
159	            }
160	            VirtualRoot::Package(package) => {
161	                format!("{package}{}", vpath.get_with_slash())
162	            }
163	        }
164	    }
165	}
166	
167	/// Static `FileId` allocated for stdin. This is to ensure that stdin can live
168	/// in the project root without colliding with any real on-disk file.
169	static STDIN_ID: LazyLock<FileId> = LazyLock::new(|| {
170	    FileId::unique(RootedPath::new(
171	        VirtualRoot::Project,
172	        VirtualPath::new("<stdin>").unwrap(),
173	    ))
174	});
175	
176	/// Static `FileId` allocated for empty/no input at all. This is to ensure that
177	/// we can create a [`SystemWorld`] based on no main file or stdin at all.
178	static EMPTY_ID: LazyLock<FileId> = LazyLock::new(|| {
179	    FileId::unique(RootedPath::new(
180	        VirtualRoot::Project,
181	        VirtualPath::new("<empty>").unwrap(),
182	    ))
183	});
184	
185	/// Provides project files from a configured directory and package files from
186	/// standard locations.
187	struct SystemFiles {
188	    main: FileId,
189	    project: FsRoot,
190	    packages: SystemPackages,
191	}
192	
193	impl SystemFiles {
194	    /// Creates a new loader given the configuration.
195	    pub fn new(
196	        input: Option<&Input>,
197	        world_args: &'static WorldArgs,
198	    ) -> Result<Self, WorldCreationError> {
199	        // Resolve the system-global input path.
200	        let input_path = match input {
201	            Some(Input::Path(path)) => {
202	                Some(path.canonicalize().map_err(|err| match err.kind() {
203	                    io::ErrorKind::NotFound => {
204	                        WorldCreationError::InputNotFound(path.clone())
205	                    }
206	                    _ => WorldCreationError::Io(err),
207	                })?)
208	            }
209	            _ => None,
210	        };
211	
212	        // Resolve the system-global root directory.
213	        let root = {
214	            let path = world_args
215	                .root
216	                .as_deref()
217	                .or_else(|| input_path.as_deref()?.parent())
218	                .unwrap_or(Path::new("."));
219	            path.canonicalize().map_err(|err| match err.kind() {
220	                io::ErrorKind::NotFound => {
221	                    WorldCreationError::RootNotFound(path.to_path_buf())
222	                }
223	                _ => WorldCreationError::Io(err),
224	            })?
225	        };
226	
227	        let main = if let Some(path) = &input_path {
228	            // Resolve the virtual path of the main file within the project root.
229	            RootedPath::new(VirtualRoot::Project, VirtualPath::virtualize(&root, path)?)
230	                .intern()
231	        } else if matches!(input, Some(Input::Stdin)) {
232	            // Return the special id of STDIN.
233	            *STDIN_ID
234	        } else {
235	            // Return the special id of EMPTY/no input at all otherwise.
236	            *EMPTY_ID
237	        };
238	
239	        Ok(Self {
240	            main,
241	            project: FsRoot::new(root),
242	            packages: crate::packages::system(&world_args.package),
243	        })
244	    }
245	
246	    /// Resolves the file system path for the given `id`.
247	    pub fn resolve(&self, id: FileId) -> FileResult<PathBuf> {
248	        self.root(id)?.resolve(id.vpath())
249	    }
250	
251	    /// Resolves the root in which the given file ID resides.
252	    fn root(&self, id: FileId) -> FileResult<FsRoot> {
253	        Ok(match id.root() {
254	            VirtualRoot::Project => self.project.clone(),
255	            VirtualRoot::Package(spec) => self.packages.obtain(spec)?,
256	        })
257	    }
258	}
259	
260	impl FileLoader for SystemFiles {
261	    fn load(&self, id: FileId) -> FileResult<Bytes> {
262	        if id == *EMPTY_ID {
263	            Ok(Bytes::new([]))
264	        } else if id == *STDIN_ID {
265	            read_from_stdin().map(Bytes::new)
266	        } else {
267	            self.root(id)?.load(id.vpath())
268	        }
269	    }
270	}
271	
272	/// Read from stdin.
273	fn read_from_stdin() -> FileResult<Vec<u8>> {
274	    let mut buf = Vec::new();
275	    let result = io::stdin().read_to_end(&mut buf);
276	    match result {
277	        Ok(_) => (),
278	        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => (),
279	        Err(err) => return Err(FileError::from_io(err, Path::new("<stdin>"))),
280	    }
281	    Ok(buf)
282	}
283	
284	/// An error that occurs during world construction.
285	#[derive(Debug)]
286	pub enum WorldCreationError {
287	    /// The input file does not appear to exist.
288	    InputNotFound(PathBuf),
289	    /// The input file path was malformed.
290	    InputMalformed(VirtualizeError),
291	    /// The root directory does not appear to exist.
292	    RootNotFound(PathBuf),
293	    /// The requested creation timestamp was invalid.
294	    InvalidTimestamp,
295	    /// Another type of I/O error.
296	    Io(io::Error),
297	}
298	
299	impl fmt::Display for WorldCreationError {
300	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
301	        match self {
302	            WorldCreationError::InputMalformed(err) => match err {
303	                VirtualizeError::Path(PathError::Escapes) => {
304	                    write!(f, "source file must be contained in project root")
305	                }
306	                VirtualizeError::Path(PathError::Backslash) => {
307	                    write!(f, "source path must not contain a backslash")
308	                }
309	                VirtualizeError::Invalid(s) => {
310	                    write!(f, "source path contains invalid sequence `{}`", s.repr())
311	                }
312	                VirtualizeError::Utf8 => write!(f, "source path must be valid UTF-8"),
313	            },
314	            WorldCreationError::InputNotFound(path) => {
315	                write!(f, "input file not found (searched at {})", path.display())
316	            }
317	            WorldCreationError::RootNotFound(path) => {
318	                write!(f, "root directory not found (searched at {})", path.display())
319	            }
320	            WorldCreationError::InvalidTimestamp => {
321	                write!(f, "creation timestamp out of range")
322	            }
323	            WorldCreationError::Io(err) => write!(f, "{err}"),
324	        }
325	    }
326	}
327	
328	impl error::Error for WorldCreationError {
329	    fn source(&self) -> Option<&(dyn error::Error + 'static)> {
330	        match self {
331	            Self::Io(error) => Some(error),
332	            _ => None,
333	        }
334	    }
335	}
336	
337	impl From<VirtualizeError> for WorldCreationError {
338	    fn from(err: VirtualizeError) -> Self {
339	        Self::InputMalformed(err)
340	    }
341	}
342	
343	impl From<WorldCreationError> for EcoString {
344	    fn from(err: WorldCreationError) -> Self {
345	        eco_format!("{err}")
346	    }
