349	impl From<Feature> for typst::Feature {
350	    fn from(feature: Feature) -> Self {
351	        match feature {
352	            Feature::Html => typst::Feature::Html,
353	            Feature::Bundle => typst::Feature::Bundle,
354	            Feature::A11yExtras => typst::Feature::A11yExtras,
